		buf.WriteString(fmt.Sprintf("  %s: %d\n", label, counts[label]))
	}

	return buf.String()
}

func actionLabel(action plans.Action) string {
	switch action {
	case plans.Create:
		return "create"
	case plans.Update:
		return "update"
	case plans.Delete:
		return "delete"
	case plans.DeleteThenCreate, plans.CreateThenDelete:
		return "replace"
	case plans.Read:
